const SCHEMA_VERSION='2.0.0';
const STORAGE_KEY='universal-bounty-workspace-v1'; // Legacy source is retained after migration.
const JOURNAL_KEY='universal-bounty-pending-v2';
const DATABASE_NAME='universal-research-workspace';
const collections=['actors','objects','boundaries','techniques','hypotheses','testCases','findings','evidence','notes','knowledgeBase','aiSuggestions','helperRecords'];
